<template>
  <section>
    <div class="snapshot-head"><h3>{{ review.purpose === 'BASELINE' ? '不可变起始基线' : review.purpose === 'PREPARE' ? '准备封存快照' : '变化核对快照' }} #{{ review.snapshotId }}</h3><span>读取时刻 {{ review.createdAt }} · 来源修订 {{ review.sourceRevision }}</span></div>
    <el-alert v-if="review.sourceRevision !== session.revision && session.state === 'DRAFT'" title="快照早于当前草稿修订，请显式检测变化并重新准备；刷新页面不表示完成重核对。" type="warning" :closable="false" />
    <div class="facts"><span>开始登记 {{ review.graph.baselineMembership.length }} 册</span><span>本波次登记 {{ review.graph.currentMembership.length }} 册</span><span>期间进入 {{ review.graph.entered.length }} 册</span><span>期间离开 {{ review.graph.left.length }} 册</span></div>
    <p>这些是登记成员集合，不是扫描库存。基线固定；借还、状态、位置、地址及身份变化仍需逐项核对。盘点不冻结馆内业务。</p>
    <details><summary>查看此时刻的登记册、地址与在借依据</summary><el-table :data="review.graph.copies" border><el-table-column label="册 / 条码" min-width="180"><template #default="{ row }">#{{ row.copyId }} · 书目 #{{ row.bookId }}<br /><code>{{ JSON.stringify(row.barcode) }}</code></template></el-table-column><el-table-column prop="stateClassification" label="状态解释" min-width="150" /><el-table-column label="登记有效位置" min-width="280"><template #default="{ row }"><CopyPlacement :placement="row.placement" :raw-text="row.rawLocation" :anomaly="row.locationReferenceAnomaly" /></template></el-table-column><el-table-column prop="actionVersion" label="册版本" width="90" /></el-table><details><summary>地址、借阅业务与背景数量证据（无会员资料）</summary><pre>{{ JSON.stringify({ addresses: review.graph.addresses, loans: review.graph.loans, books: review.graph.books }, null, 2) }}</pre></details></details>
    <h3>明确覆盖声明</h3>
    <el-table :data="scopeItems" border><el-table-column label="固定范围项" min-width="150"><template #default="{ row }">{{ session.scope.kind === 'ADDRESS_SET' ? '地址' : '实体册' }} #{{ row.id }}</template></el-table-column><el-table-column label="该快照声明" min-width="220"><template #default="{ row }">{{ coverageLabels[row.coverage?.status || 'NOT_ATTEMPTED'] }}<br />{{ row.coverage?.reason ?? '尚无声明' }}<br />{{ row.coverage?.acceptedAt ?? '' }}</template></el-table-column><el-table-column v-if="editable" label="追加本项声明" min-width="310"><template #default="{ row }"><select v-model="coverageDraft[row.id]" :disabled="locked"><option v-for="(label, value) in coverageLabels" :key="value" :value="value">{{ label }}</option></select><el-button :disabled="locked" @click="saveCoverage(row.id)">保存本项声明</el-button></template></el-table-column></el-table>
    <p>“所选有限范围检查完成”要求每项明确 COMPLETE。未检查或部分检查的未见册只列“尚未观察到”；部分报告仍保留未覆盖项。</p>
    <template v-if="editable">
      <el-input v-model="reason" maxlength="500" :disabled="locked" placeholder="本次覆盖、变化检测、准备或取消依据（1–500 字）" />
      <div class="toolbar"><el-button :disabled="locked" @click="write('检测期间变化', 'change-checks', {})">检测期间变化</el-button><select v-model="completionKind" :disabled="locked"><option value="PARTIAL">部分盘点报告</option><option value="COMPLETE_SCOPE">所选有限范围检查完成</option></select><el-button type="primary" :disabled="locked" @click="write('准备封存报告', 'prepares', { completionKind })">准备封存预览</el-button><el-button type="danger" plain :disabled="locked" @click="cancelVisible = !cancelVisible">取消本草稿</el-button></div>
      <div v-if="cancelVisible" class="cancel-panel"><p>取消保留全部事实，归档为未完成证据；不能恢复为完成报告。</p><el-button type="danger" :disabled="locked" @click="write('取消未完成盘点', 'cancel', {})">确认取消并保留事实</el-button></div>
    </template>
    <h3>需要重核对的变化</h3>
    <el-form inline @submit.prevent="search"><el-form-item label="变化类别"><select v-model="category"><option value="">全部</option><option v-for="value in ['COPY','LOAN','ADDRESS','BOOK','SCOPE','BARCODE']" :key="value" :value="value">{{ categoryLabels[value] }}</option></select></el-form-item><el-form-item label="册 ID"><el-input v-model="copyFilter" placeholder="稳定册 ID" /></el-form-item><el-button @click="search">查询变化页</el-button></el-form>
    <el-table :data="changes" border v-loading="loading"><el-table-column label="受影响项" min-width="200"><template #default="{ row }">{{ categoryLabels[row.category] }} · {{ row.entityKey }}<br /><span v-if="row.copyId">册 #{{ row.copyId }}</span></template></el-table-column><el-table-column label="核对要求" min-width="230"><template #default="{ row }">{{ row.category === 'BOOK' ? '背景数量变化，核对说明' : '读取新的依据并明确核对本项' }}<p>检测和刷新均不自动接受变化。</p></template></el-table-column><el-table-column v-if="editable" label="操作" width="160"><template #default="{ row }"><el-button link :disabled="locked" @click="selectChange(row)">逐项重新核对</el-button></template></el-table-column></el-table>
    <el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="loadChanges" />
    <section v-if="selectedChange && editable" class="recheck-panel"><h4>核对 {{ selectedChange.entityKey }}</h4><select v-model="decision" :disabled="locked"><option v-if="['COPY','LOAN'].includes(selectedChange.category)" value="OBSERVED_AGAIN">重新看到实体册</option><option v-if="['COPY','LOAN'].includes(selectedChange.category)" value="CHECKED_NOT_SEEN">已实际检查，未看到</option><option v-if="['COPY','LOAN'].includes(selectedChange.category)" value="LEGITIMATE_LOAN">核实有效在借</option><option value="CONFIRM_EXPLANATION">记录本项检查说明</option></select><el-input v-model="evidence" type="textarea" :disabled="locked" maxlength="500" placeholder="本项实际核对依据；物理册说明须写明检查过程" /><el-button type="primary" :disabled="locked" @click="saveRecheck">保存本项重核对</el-button><el-button :disabled="locked" @click="selectedChange = null">放弃未保存输入</el-button></section>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <section v-if="review.purpose === 'PREPARE'" class="seal-panel"><h3>{{ completenessLabels[review.completionKind || 'PARTIAL'] }}</h3><p>预览有效至 {{ review.expiresAt }}。检查完成仍可含待核实差异，不能解释为库存相符或全馆完成。</p><p>快照待核对变化 {{ review.changes.length }} 项 · 差异标签 {{ review.differenceIds.length }} 条</p><el-button v-if="admin && session.state === 'DRAFT'" type="success" :disabled="locked || !canSeal" @click="write('管理员封存报告', 'confirm', { reviewSnapshotId: review.snapshotId, previewDigest: review.digest })">管理员最终确认并封存</el-button><p v-else-if="session.state === 'DRAFT'">预览已准备，需管理员最终确认。</p><p v-if="!canSeal && session.state === 'DRAFT'">尚有变化、覆盖未完成或预览过期，请完成核对后重新准备。</p></section>
  </section>
</template>
<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { getStocktakeChanges, type Change, type CompletionKind, type RecheckItem, type Review, type StocktakeSession } from '@/api/stocktake'
import CopyPlacement from '@/components/locations/CopyPlacement.vue'
import { completenessLabels, coverageLabels, parseExplicitIds } from './stocktakeInput'
const props = defineProps<{ session: StocktakeSession; review: Review; editable: boolean; admin: boolean; locked: boolean; refresh: number }>()
const emit = defineEmits<{ write: [label: string, suffix: string, body: Record<string, unknown>, onSuccess?: () => void] }>()
const reason = ref(''), completionKind = ref<CompletionKind>('PARTIAL'), cancelVisible = ref(false), error = ref('')
const coverageDraft = reactive<Record<number, string>>({})
const scopeItems = computed(() => (props.session.scope.kind === 'ADDRESS_SET' ? props.session.scope.locationIds : props.session.scope.copyIds).map(id => ({ id, coverage: props.review.coverage.find(item => item.scopeItemId === id) })))
const canSeal = computed(() => props.review.purpose === 'PREPARE' && props.review.sourceRevision === props.session.revision && !props.review.changes.length && !!props.review.expiresAt && Date.parse(props.review.expiresAt) > Date.now() && (props.review.completionKind === 'PARTIAL' || scopeItems.value.every(item => item.coverage?.status === 'COMPLETE')))
const categoryLabels: Record<string, string> = { COPY: '实体册', LOAN: '借阅', ADDRESS: '地址结构', BOOK: '书目背景', SCOPE: '范围成员', BARCODE: '条码身份' }
const changes = ref<Change[]>([]), category = ref(''), copyFilter = ref(''), page = ref(1), total = ref(0), loading = ref(false)
const selectedChange = ref<Change | null>(null), decision = ref<RecheckItem['decision']>('CONFIRM_EXPLANATION'), evidence = ref('')
function validReason(value: string) { if (!value.trim() || [...value].length > 500) throw new Error('请填写 1–500 字依据。'); return value }
function write(label: string, suffix: string, body: Record<string, unknown>, onSuccess?: () => void) { try { emit('write', label, suffix, { reason: validReason(reason.value), ...body }, onSuccess); error.value = '' } catch (cause) { error.value = (cause as Error).message } }
function saveCoverage(id: number) { write('追加覆盖声明', 'coverage', { items: [{ scopeItemId: id, status: coverageDraft[id] || 'NOT_ATTEMPTED' }] }) }
function selectChange(row: Change) { selectedChange.value = row; decision.value = 'CONFIRM_EXPLANATION'; evidence.value = '' }
function saveRecheck() { if (!selectedChange.value) return; try { const row = selectedChange.value; const item: RecheckItem = { entityKey: row.entityKey, changeToken: row.changeToken, expectedSignatureDigest: row.expectedSignatureDigest, decision: decision.value, evidence: validReason(evidence.value) }; write('逐项重核对', 'rechecks', { items: [item] }, () => { selectedChange.value = null }) } catch (cause) { error.value = (cause as Error).message } }
let request = 0
async function loadChanges() { const current = ++request; loading.value = true; try { const copyId = copyFilter.value ? parseExplicitIds(copyFilter.value, 1)[0] : undefined; const result = await getStocktakeChanges(props.session.sessionId, { snapshotId: props.review.snapshotId, page: page.value, size: 20, category: category.value || undefined, copyId }); if (current === request) { changes.value = result.records; total.value = result.total } } catch { if (current === request) { changes.value = []; total.value = 0; error.value = '变化页读取失败，请保留输入后重试。' } } finally { if (current === request) loading.value = false } }
function search() { page.value = 1; loadChanges() }
watch(() => props.review.snapshotId, () => { selectedChange.value = null; for (const item of scopeItems.value) coverageDraft[item.id] = item.coverage?.status || 'NOT_ATTEMPTED'; page.value = 1; loadChanges() }, { immediate: true })
watch(() => props.refresh, loadChanges)
</script>
<style scoped>
.snapshot-head { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }.snapshot-head h3 { margin: 8px 0; }.snapshot-head span,p { color: #65758b; font-size: 13px; line-height: 1.7; }.facts,.toolbar { display: flex; flex-wrap: wrap; gap: 14px; margin: 16px 0; }.facts span { background: #f0f5fc; padding: 12px; border-radius: 6px; }select { min-height: 32px; border: 1px solid #dcdfe6; border-radius: 4px; padding: 4px 10px; }.recheck-panel,.seal-panel,.cancel-panel { background: #f6f9fd; padding: 16px; border-radius: 8px; margin: 16px 0; display: grid; gap: 12px; }.seal-panel { border: 1px solid #c5dccb; }pre,code { white-space: pre-wrap; overflow-wrap: anywhere; }
</style>
